import{_ as t,o as l,c as r,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"Ceph Telemetry- The Why, What, and How. Yaarit Hatuka from IBM","description":"","frontmatter":{"title":"Ceph Telemetry- The Why, What, and How. Yaarit Hatuka from IBM","date":"2025-05-08T00:00:00.000Z","updated":"2025-05-09T00:00:00.000Z","tags":["Ceph","Distributed Storage","Telemetry","Data Analysis","Open Source"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ceph_Telemetry_-_The_Why_What_and_How._Yaarit_Hatuka_from_IBM.md","filePath":"posts/2025/Ceph_Telemetry_-_The_Why_What_and_How._Yaarit_Hatuka_from_IBM.md","lastUpdated":1780459816000}'),a={name:"posts/2025/Ceph_Telemetry_-_The_Why_What_and_How._Yaarit_Hatuka_from_IBM.md"};function _(o,e,p,s,n,m){return l(),r("div",null,[...e[0]||(e[0]=[i("<p>Ceph Telemetry 项目旨在通过自动收集和分析集群数据，帮助开发者和用户更好地理解和优化 Ceph 部署。以下是对会议内容的详细总结：</p><p><strong>会议概述</strong>： 会议主要讨论了 Ceph Telemetry 项目的背景、功能、数据收集方式、用户隐私保护以及如何通过 Telemetry 数据改进 Ceph 的开发和用户支持。</p><p><strong>主要议题</strong>：</p><ol><li><p><strong>Telemetry 的定义与背景</strong>：</p><ul><li>Telemetry 源于航天和电信领域，用于自动记录和传输远程数据进行分析。</li><li>在 Ceph 中，Telemetry 用于收集集群的运行状态、版本信息、硬件配置、崩溃报告等数据。</li></ul></li><li><p><strong>Telemetry 的作用</strong>：</p><ul><li>帮助开发者了解用户的使用情况和问题，实时了解新功能的采用率、硬件使用情况、崩溃趋势等。</li><li>用户可以通过 Telemetry 验证其部署，了解常见问题及其解决方案。</li></ul></li><li><p><strong>Telemetry 服务概述</strong>：</p><ul><li>自 Mimic 版本引入，已有约 3.7 万个集群参与，总存储容量达 1.7 Exabytes，OSD 数量超过 20.5 万个。</li><li>数据收集分为多个通道，包括基本通道、崩溃通道、设备通道等。</li></ul></li><li><p><strong>数据收集与隐私保护</strong>：</p><ul><li>默认关闭，用户需主动选择加入并同意相关许可协议。</li><li>数据收集过程中，所有敏感信息被匿名化处理，且不会收集日志。</li></ul></li><li><p><strong>Telemetry 数据的应用</strong>：</p><ul><li>了解不同版本的采用情况，展示用户使用的存储设备类型及其利用率。</li><li>通过 Redmine 问题跟踪系统关联崩溃数据，帮助开发者快速定位和修复问题。</li></ul></li><li><p><strong>Telemetry 的未来改进</strong>：</p><ul><li>进一步了解未参与的集群情况，找到解决方案以鼓励更多用户参与。</li><li>继续优化数据处理和隐私保护机制，确保用户数据的安全性和匿名性。</li></ul></li></ol><p><strong>决定事项与后续行动计划</strong>：</p><ol><li>鼓励更多用户参与 Telemetry。</li><li>继续优化崩溃数据处理。</li><li>提升 Telemetry 数据的可视化与分析能力。</li><li>探索与其他工具的集成，进一步扩展 Telemetry 的应用场景。</li></ol><p>通过 Telemetry，Ceph 项目的开发者和用户将能够更好地理解和优化 Ceph 部署，从而提高系统的稳定性和性能。</p>",7)])])}const y=t(a,[["render",_]]);export{h as __pageData,y as default};
